CREATE TABLE shop_services(id SERIAL PRIMARY KEY,room_id INTEGER UNIQUE NOT NULL REFERENCES rooms(id),mob_template_id INTEGER NOT NULL REFERENCES mob_templates(id),open_hour INTEGER NOT NULL DEFAULT 7 CHECK(open_hour BETWEEN 0 AND 25),close_hour INTEGER NOT NULL DEFAULT 21 CHECK(close_hour BETWEEN 0 AND 25));
ALTER TABLE relics ADD COLUMN min_level INTEGER NOT NULL DEFAULT 50 CHECK(min_level BETWEEN 50 AND 99);
